<template><section aria-label="文本差异对比"><p class="tool-note">逐行对比并标注新增、删除及未变内容。默认统一 CRLF / LF；最后一行无换行会单独标记。两段合计最多 20 万字符、4000 行。</p><div class="tool-two-column"><label class="tool-label">旧文本<textarea v-model="before" aria-label="差异旧文本" spellcheck="false"></textarea></label><label class="tool-label">新文本<textarea v-model="after" aria-label="差异新文本" spellcheck="false"></textarea></label></div><div class="tool-actions"><label><input v-model="ignoreWhitespace" type="checkbox" />忽略行首尾空白</label><button type="button" :disabled="busy" @click="compare">{{busy?'正在对比…':'对比文本'}}</button><button type="button" @click="swap">交换两侧</button><button type="button" @click="before='';after='';invalidate()">清空对比</button></div><p v-if="error" class="tool-error" role="alert">{{error}}</p><template v-if="result"><p role="status">新增 {{result.added}} 行 · 删除 {{result.removed}} 行{{result.added===0&&result.removed===0?' · 两段文本一致（按当前选项）':''}}</p><div class="diff-view" aria-label="差异结果"><div v-for="(row,index) in result.rows" :key="index" class="diff-row" :class="row.kind"><span class="diff-number">{{row.oldLine??'—'}}</span><span class="diff-number">{{row.newLine??'—'}}</span><span class="diff-marker">{{row.kind==='added'?'+':row.kind==='removed'?'−':' '}}</span><code>{{row.text||'（空行）'}}<small v-if="row.noNewline"> [无行尾换行]</small></code></div></div><button type="button" @click="copy">复制差异结果</button></template><p role="status">{{message}}</p></section></template>
<script>
import { compareLines } from '../../utils/extended-tools.mjs';
export default {name:'DiffTool',data:()=>({before:'',after:'',ignoreWhitespace:false,result:null,busy:false,error:'',message:'',request:0}),watch:{before(){this.invalidate();},after(){this.invalidate();},ignoreWhitespace(){this.invalidate();}},beforeUnmount(){++this.request;},methods:{invalidate(){++this.request;this.result=null;this.busy=false;this.error='';this.message='';},swap(){[this.before,this.after]=[this.after,this.before];},async compare(){const request=++this.request;this.busy=true;this.error='';this.result=null;try{const result=await compareLines(this.before,this.after,this.ignoreWhitespace);if(request===this.request)this.result=result;}catch(error){if(request===this.request)this.error=error.message;}finally{if(request===this.request)this.busy=false;}},async copy(){try{await navigator.clipboard.writeText(this.result.rows.map(r=>(r.kind==='added'?'+':r.kind==='removed'?'-':' ')+r.text).join('\n'));this.message='已复制带差异标记的文本（不是补丁文件）';}catch{this.message='复制未完成，请选择差异内容手动复制';}}}};
</script>
<style scoped>.diff-view{max-height:450px;overflow:auto;border:1px solid var(--el-border-color);border-radius:8px;margin:12px 0;}.diff-row{display:grid;grid-template-columns:38px 38px 20px minmax(0,1fr);gap:4px;padding:5px;line-height:1.6;}.diff-number{color:var(--el-text-color-secondary);text-align:right;font-size:11px;}.diff-row code{white-space:pre-wrap;overflow-wrap:anywhere;}.diff-row.added{background:var(--el-color-success-light-9,#edf9ee);}.diff-row.removed{background:var(--el-color-danger-light-9,#fff0f0);}.diff-marker{font-weight:bold;text-align:center;}.diff-row small{color:var(--el-text-color-secondary);}</style>
